import{_ as i,C as t,c as r,o as s,aj as p,G as o,w as h}from"./chunks/framework.Bfdr4H5E.js";const f=JSON.parse('{"title":"The Journey","description":"","frontmatter":{"outline":"deep","prev":{"text":"FACT Most Traders Will Fail to Achieve Consistent Profitability","link":"/trading-with-pav/fact-most-traders-will-fail-to-achieve-consistent-profitability"},"next":{"text":"Deliberate Practice","link":"/trading-with-pav/deliberate-practice"}},"headers":[],"relativePath":"trading-with-pav/the-journey.md","filePath":"trading-with-pav/the-journey.md"}'),l={name:"trading-with-pav/the-journey.md"};function u(d,e,c,m,y,g){const a=t("GraphComment"),n=t("ClientOnly");return s(),r("div",null,[e[0]||(e[0]=p('<h1 id="the-journey" tabindex="-1">The Journey <a class="header-anchor" href="#the-journey" aria-label="Permalink to &quot;The Journey&quot;">​</a></h1><p>Success in trading does not come from a <em>Holy Grail</em> strategy that you simply implement with discipline. You can’t just GET a trading system or strategy; you have to BECOME a trader. It’s a journey of trial and error; of two steps forward and one step back; of growth and development.</p><p>It’s the infinite variations on the patterns, within an environment of uncertainty, being executed and managed by a trader, handicapped by fear based heuristics, biases and flawed decision making processes, that make this game so hard.</p><div class="warning custom-block"><p class="custom-block-title">Key to your is your personal journey</p><p><strong>I can’t give you a solution – its journey that you have to take; a process of growth and development. All I can do is point you in the right direction.</strong></p></div><p>Learn to read the price action with volume. Determine the market environment. Learn to place current price action volume into the context of the larger timeframe price action.</p><p>Identify areas of opportunity within that environment. Find a low risk entry position. Get in. Manage the hell out of the trade, in order to firstly minimize risk and secondly maximize opportunity.</p><p>Make a ton of mistakes. Review them. Learn from them. Repeat them over and over until it finally sinks in. Grow and improve.</p><p>It’s not about simple, objective entry and exit rules. It’s about knowing when to take the setup and when to avoid it (based on context and the current nature of price action volume).</p><p>It’s about knowing when to use a pullback entry or when to take a breakout entry. It’s about knowing when to scratch a trade, rather than hold on hoping for it to reach the target.</p><p>It’s about learning to be ok with being wrong. It’s about learning to TRUST yourself. It’s about learning to TRUST the strategy.</p><p>It’s about forgiving yourself when you make mistakes. Again and again and again!</p><p>It’s about being ok with losses, and with stopping out to the tick before the market moves on without you, because you’ve seen this enough times to know that it’s just part of the game, and you can simply move on to the next setup secure in the knowledge that new equity highs are just around the corner.</p><p>This all takes time – exposure to the markets – exposure to the process of making decisions and taking action – exposure to error.</p><p>It’s not about certainty. It’s about becoming comfortable operating in an environment of uncertainty. Knowing that you don’t know what’s going to happen next, and being ok with that.</p><p>Knowing that even though you don’t know where price will go next, you have proven through experience that you have the skills, knowledge and attitude required to manage the opportunity appropriately to minimize risk or maximize gain, regardless of which eventuates.</p><p>Learning to trade is NOT learning a price action volume setup. It is a process of BECOMING a trader.</p><p>It is a journey of growth and development – developing your perceptual abilities; developing your awareness of risk; developing your decision making abilities; developing your tolerance for uncertainty.</p><p>Learning to trade is a process of Trader Development.</p><p>Until you accept that, you’ll never make it. You’ll be stuck in the search for the simple trading system or strategy.</p><p>The analysis process in “Module 3 : MARKETS &amp; MARKET ANALYSIS” and the strategy in “Module 4 : TRADING STRATEGY” simply provided you with the tools for interacting with the market. Now you have to learn how to trade them.</p><p>It’s not easy. But me and others have made it and so can you.</p><p>The following articles will help you along your journey.</p><p><a href="/sk/trading-with-pav/deliberate-practice-tools-and-techniques/">Article 93</a> will provide you with the tools and techniques to ensure you progress as fast as possible. And <a href="/sk/trading-with-pav/the-development-stages/">article 94</a> will get you started on your first steps, laying out a roadmap for the journey ahead.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',24)),o(n,null,{default:h(()=>[o(a)]),_:1})])}const v=i(l,[["render",u]]);export{f as __pageData,v as default};
